<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Tall Guy and a Grill Catering</title>
    <style>
        :root {
            --primary-red: #a63c2b;
            --primary-dark: #8a2f21;
            --accent-orange: #d97b2e;
            --text-dark: #333333;
            --text-light: #666666;
            --bg-light: #fdfdfd;
            --font-serif: "Georgia", "Times New Roman", serif;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-sans);
            color: var(--text-dark);
            line-height: 1.6;
            background-color: var(--bg-light);
        }

        a { text-decoration: none; color: inherit; }
        ul { list-style: none; }
        img { max-width: 100%; display: block; object-fit: cover; }

        /* --- Header --- */
        header {
            background-color: var(--primary-red);
            color: white;
            padding: 20px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            position: sticky;
            top: 0;
            z-index: 1000;
        }

        .nav-left {
            display: flex;
            gap: 20px;
            font-size: 13px;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 500;
        }

        .nav-left a:hover { opacity: 0.8; }

        .logo-container {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            text-align: center;
        }

        .logo-text {
            font-family: var(--font-serif);
            font-size: 24px;
            font-weight: bold;
            letter-spacing: 1px;
            line-height: 1;
        }

        .logo-sub {
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: 2px;
            border-top: 1px solid rgba(255,255,255,0.5);
            border-bottom: 1px solid rgba(255,255,255,0.5);
            padding: 2px 4px;
            display: inline-block;
            margin-top: 2px;
        }

        .nav-right {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .social-icons a {
            color: white;
            font-size: 14px;
            opacity: 0.9;
        }

        .btn-reach-out {
            background-color: white;
            color: var(--primary-red);
            padding: 10px 24px;
            border-radius: 20px;
            font-weight: bold;
            font-size: 12px;
            transition: transform 0.2s;
        }

        .btn-reach-out:hover { transform: scale(1.05); }

        /* --- Hero Section --- */
        .hero {
            height: 600px;
            width: 100%;
            position: relative;
            background-image: url('https://images.unsplash.com/photo-1546039907-7fa05f864c02?ixlib=rb-4.0.3&auto=format&fit=crop&w=1600&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
        }

        .hero-overlay {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(0,0,0,0.15); /* Subtle overlay */
        }

        .hero-content {
            position: relative;
            z-index: 2;
            color: white;
            max-width: 800px;
            padding: 20px;
            text-shadow: 0 2px 4px rgba(0,0,0,0.3);
        }

        .hero h1 {
            font-family: var(--font-serif);
            font-size: 42px;
            font-weight: normal;
            line-height: 1.3;
        }

        /* --- Content Sections (Zig Zag) --- */
        .section-container {
            padding: 80px 60px;
            max-width: 1200px;
            margin: 0 auto;
        }

        .feature-row {
            display: flex;
            align-items: center;
            gap: 60px;
            margin-bottom: 80px;
            border-bottom: 1px solid #ddd;
            padding-bottom: 80px;
        }

        .feature-row:last-child {
            border-bottom: none;
            margin-bottom: 0;
            padding-bottom: 0;
        }

        .feature-row.reverse {
            flex-direction: row-reverse;
        }

        .text-col {
            flex: 1;
        }

        .img-col {
            flex: 1;
            height: 350px;
        }

        .img-col img {
            width: 100%;
            height: 100%;
            border-radius: 2px;
        }

        h2.section-title {
            color: var(--primary-red);
            font-family: var(--font-sans);
            font-size: 28px;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 20px;
            font-weight: 500;
        }

        p.section-desc {
            color: var(--text-light);
            font-size: 15px;
            line-height: 1.8;
        }

        /* --- Testimonial Section --- */
        .testimonial-section {
            padding: 100px 20px;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .testimonial-box {
            background-color: var(--primary-red);
            color: white;
            padding: 60px 50px;
            max-width: 800px;
            width: 100%;
            font-family: var(--font-serif);
            font-style: italic;
            font-size: 18px;
            line-height: 1.6;
            position: relative;
        }

        .testimonial-author {
            margin-top: 25px;
            font-style: normal;
            font-family: var(--font-sans);
            font-size: 14px;
            opacity: 0.9;
        }

        /* --- Social Section --- */
        .social-section {
            text-align: center;
            padding: 60px 20px 100px;
        }

        .social-title {
            color: var(--primary-red);
            font-family: var(--font-serif);
            font-size: 32px;
            font-weight: normal;
            margin-bottom: 60px;
        }

        .social-grid {
            display: flex;
            justify-content: center;
            gap: 150px;
        }

        .play-icon-placeholder {
            width: 30px;
            height: 30px;
            opacity: 0.5;
            cursor: pointer;
        }

        .play-icon-placeholder svg {
            fill: #ccc;
            width: 100%; height: 100%;
        }

        /* --- Footer / Subscribe --- */
        footer {
            margin-top: auto;
        }

        .subscribe-area {
            background-color: var(--accent-orange);
            padding: 60px 40px;
            text-align: center;
            color: white;
        }

        .subscribe-text {
            font-size: 16px;
            margin-bottom: 30px;
            font-weight: 300;
        }

        .form-row {
            display: flex;
            justify-content: center;
            gap: 15px;
            max-width: 900px;
            margin: 0 auto;
            flex-wrap: wrap;
        }

        .sub-input {
            padding: 15px 20px;
            border: none;
            border-radius: 2px;
            width: 250px;
            font-size: 14px;
            outline: none;
        }

        .btn-subscribe {
            background-color: white;
            color: var(--accent-orange);
            border: none;
            padding: 15px 35px;
            border-radius: 20px;
            font-weight: bold;
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 1px;
            cursor: pointer;
            transition: background 0.2s;
        }

        .btn-subscribe:hover {
            background-color: #fff5eb;
        }

        .footer-bottom {
            background-color: var(--primary-dark);
            padding: 40px;
            text-align: center;
            color: rgba(255,255,255,0.6);
            font-size: 11px;
        }

        .footer-links span {
            margin: 0 5px;
            text-decoration: underline;
            cursor: pointer;
        }

        /* Responsive */
        @media (max-width: 900px) {
            header { padding: 15px 20px; }
            .logo-container { position: static; transform: none; order: 1; margin-right: auto;}
            .nav-left { display: none; } /* Simplified for mobile view based on typical patterns, though screenshot is desktop */

            .feature-row, .feature-row.reverse {
                flex-direction: column;
                gap: 30px;
                padding-bottom: 50px;
            }

            .img-col { width: 100%; height: 300px; }

            .form-row { flex-direction: column; align-items: center; }
            .sub-input { width: 100%; max-width: 400px; }
        }
    </style>
</head>
